const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const roi = ee.Geometry.Polygon([
      [-122.7, 40.9],
      [-117.5, 40.9],
      [-117.5, 35.0],
      [-122.7, 35.0],
      [-122.7, 40.9]
    ], null, false);

    const dates = [
      '2022-01-01',
      '2022-04-01',
      '2022-05-04'
    ];

    const SCALE = 1000;
    const MAXPIX = 1e9;

    // High elevation mask to approximate Sierra Nevada mountains
    const srtm = ee.Image('USGS/SRTMGL1_003');
    const highMask = srtm.gte(1200).selfMask(); // >=1200 m

    // Helper: fetch MODIS snow image with fallback logic
    async function fetchSnowImage(dateStr) {
      const target = ee.Date(dateStr);
      const ids = ['MODIS/061/MOD10A1', 'MODIS/006/MOD10A1'];
      let usedId = null;
      let win = 0;
      let sizeInfo = 0;
      let img = null;

      for (win = 0; win <= 3; win++) { // expand ±days window up to 3
        const start = target.advance(-win, 'day');
        const end = target.advance(win + 1, 'day'); // end-exclusive
        for (let i = 0; i < ids.length; i++) {
          const col = ee.ImageCollection(ids[i])
            .filterDate(start, end)
            .filterBounds(roi)
            .select(['NDSI_Snow_Cover']);
          sizeInfo = await col.size().getInfo();
          if (sizeInfo > 0) {
            // Mosaic over window; MODIS values are categorical/percent; mosaic picks last per pixel
            img = col.mosaic().set({'used_start': start.format('YYYY-MM-dd'), 'used_end': end.format('YYYY-MM-dd')});
            usedId = ids[i];
            return {img, usedId, win, size: sizeInfo};
          }
        }
      }
      return {img: null, usedId: null, win: null, size: 0};
    }

    // Compute metrics for a given image/date
    async function computeMetrics(img) {
      // Valid MODIS snow values are 0..100; others (e.g., 239 cloud) are invalid
      const snow = img.select('NDSI_Snow_Cover');
      const validMask = snow.gte(0).and(snow.lte(100));
      const valid = validMask.and(highMask).selfMask();

      const totalPix = ee.Image(1).updateMask(highMask).rename('c');
      const snowPix = snow.gt(0).and(validMask).and(highMask).selfMask().rename('snowpix');

      const totalCount = await totalPix.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: SCALE,
        maxPixels: MAXPIX
      }).get('c').getInfo();

      const validCount = await ee.Image(1).updateMask(valid).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: SCALE,
        maxPixels: MAXPIX
      }).get('constant').getInfo();

      const snowCount = await snowPix.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: SCALE,
        maxPixels: MAXPIX
      }).get('snowpix').getInfo();

      // Guard checks
      if (totalCount === null || isNaN(totalCount) || totalCount === 0) {
        return {status: 'C3'};
      }
      if (validCount === null || isNaN(validCount)) {
        return {status: 'C3'};
      }
      if (validCount === 0) {
        return {status: 'C2'};
      }
      if (snowCount === null || isNaN(snowCount)) {
        return {status: 'C3'};
      }

      const cloudFrac = Math.max(0, (totalCount - validCount) / totalCount);
      const snowFracTotal = snowCount / totalCount;

      return {
        status: 'OK',
        totalCount,
        validCount,
        snowCount,
        cloudPct: 100 * cloudFrac,
        snowPctTotal: 100 * snowFracTotal
      };
    }

    console.log('ROI: Sierra Nevada approx (35–40.9N, -122.7–-117.5), elev>=1200 m, scale=1000 m');

    const results = [];
    for (const d of dates) {
      const fetched = await fetchSnowImage(d);
      if (!fetched.img) {
        console.log(`${d} Images: 0`);
        console.log('C1');
        return;
      }
      const metrics = await computeMetrics(fetched.img);
      if (metrics.status !== 'OK') {
        console.log(`${d} Images: ${fetched.size} (window ±${fetched.win}d, ${fetched.usedId})`);
        console.log(metrics.status);
        return;
      }
      const usedStart = await fetched.img.get('used_start').getInfo();
      const usedEnd = await fetched.img.get('used_end').getInfo();
      console.log(`${d} imgs:${fetched.size} win:±${fetched.win} src:${fetched.usedId.split('/').slice(0,3).join('/')} valid:${metrics.validCount} total:${metrics.totalCount} cloud%:${metrics.cloudPct.toFixed(1)} snow%:${metrics.snowPctTotal.toFixed(1)} [${usedStart}..${usedEnd})`);
      results.push({date: d, snowPct: metrics.snowPctTotal});
    }

    // 5. Validation & Final Answer
    const jan = results.find(r => r.date === '2022-01-01')?.snowPct;
    const apr = results.find(r => r.date === '2022-04-01')?.snowPct;
    const may = results.find(r => r.date === '2022-05-04')?.snowPct;

    if ([jan, apr, may].some(v => v === null || v === undefined || isNaN(v))) {
      console.log('C3');
      return;
    }

    // Compare: Was there more snow on Jan 1 than on Apr 1 and May 4?
    const moreOnJan = (jan > apr) && (jan > may);
    console.log(`Compare snow% total — Jan1:${jan.toFixed(2)} > Apr1:${apr.toFixed(2)} and May4:${may.toFixed(2)} ? ${moreOnJan ? 'Yes' : 'No'}`);
    console.log(moreOnJan ? 'A' : 'B');
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
